const exerciseInventory=JSON.parse(read(src+'/exercise-inventory.json'));
const exerciseMap=new Map(coverage.exercises.map(x=>[x.id,x]));
const problemRows=exerciseInventory.problems.map(p=>({...p,record:exerciseMap.get(p.id)}));
const catalogLabels=require('./src/catalog-labels.cjs');
let exerciseHTML=head('全书习题导航')+mast+`<main id="main"><header class="hero"><div class="eyebrow">TEXTBOOK PROBLEMS</div><h1>跟着例子，学会证明。</h1><a href="learn.html">进入全书随题图解 →</a><p>目录收录 ${problemCount} 道章末题，当前${coverage.exercises.length}道已有讲解入口。入口表示已整理，独立完成原题与迁移题后再检查是否掌握。</p></header><div class="coverage-note">第 3 章原书题号从 5 跳到 7。第 7 章收录至印刷第 102 页的优惠券和计件合同。每个入口的条件、原文校准与未解决点写在实验里。第2章有15份、第5章有14份、第10章有20份、第15章有23份、第16章有19份、第20章有17份按小问独立运行的HTML代码；竞赛唯一性、出资等号和永久等待成本的原文条件已单列。</div><div class="catalog-tools"><input id="search" type="search" aria-label="搜索习题" placeholder="搜索题号或主题，例如15.17"><select id="filter" aria-label="筛选习题"><option value="all">全部题目</option><option value="ready">已有讲解入口</option></select></div><p id="found" class="small" data-unit="道习题" aria-live="polite"></p>`;
for(let chapter=1;chapter<=20;chapter++)exerciseHTML+=`<section class="chapter" id="exercises-${chapter}"><div class="section-heading"><h2>${String(chapter).padStart(2,'0')} / ${chapters[chapter-1]}</h2></div><div class="chapter-rows">${problemRows.filter(x=>x.chapter===chapter).map(p=>{const e=p.record,displayScope=catalogLabels[p.id]||e?.scope||'原题实验';return `<div class="lesson-row" data-ready="${e?'yes':'no'}" data-id="${p.id}" data-search="${esc((p.id+' '+(e?.scope||'')+' '+displayScope).toLowerCase())}"><span class="num">${p.number}</span><div><h3>${e?`<a href="${p.chapter<=guidedChapters?guideURL('p'+p.chapter+'.'+p.number):e.entry}"><span>${esc(p.id.replace('Problem','习题'))}</span> · <span>${esc(displayScope)}</span></a>`:esc(p.id.replace('Problem','习题')+' · 正在补充')}</h3><p>印刷第${p.printedPage}页${e?' · '+Object.entries(e.partScenarios||{}).map(([part,k])=>`<a href="${e.evidence?.find(x=>x.scenario===k)?.entry||`lesson-${e.section.replace('.','-')}.html?case=${k}`}">(${esc(part)})</a>`).join(' '):''}</p></div><span class="status">${e?'已建入口':'待补全'}</span></div>`}).join('')}</div></section>`;
exerciseHTML+='</main>'+end('');write(out+'/exercises.html',exerciseHTML);write(out+'/exercise-inventory.json',JSON.stringify(exerciseInventory,null,2));

for(const v of require('./src/choice-intro-downloads.cjs'))write(out+'/downloads/ch2-intro-'+v.name+'.html',read(out+'/downloads/lesson-2-1.html').replace('<script type="module">','<script>window.CHOICE_INTRO_DEFAULT='+JSON.stringify(v.mode)+';window.CHOICE_INTRO_INITIAL='+JSON.stringify(v.initial)+';</script><script type="module">'));

for(const v of require('./src/rationalization-downloads.cjs'))write(out+'/downloads/ch2-rz-'+v.name+'.html',read(out+'/downloads/lesson-2-2.html').replace('<script type="module">','<script>window.RZ_DEFAULT='+JSON.stringify(v.mode)+';window.RZ_INITIAL='+JSON.stringify(v.initial)+';</script><script type="module">'));

for(const v of require('./src/alpha-downloads.cjs'))write(out+'/downloads/ch2-alpha-'+v.name+'.html',read(out+'/downloads/lesson-2-3.html').replace('<script type="module">','<script>window.ALPHA_DEFAULT='+JSON.stringify(v.mode)+';window.ALPHA_INITIAL='+JSON.stringify(v.initial)+';</script><script type="module">'));

for(const v of require('./src/sequential-downloads.cjs'))write(out+'/downloads/ch2-sequential-'+v.name+'.html',read(out+'/downloads/lesson-2-'+(v.mode==='moneypump'?5:4)+'.html').replace('<script type="module">','<script>window.SD_DEFAULT='+JSON.stringify(v.mode)+';window.SD_INITIAL='+JSON.stringify(v.initial)+';</script><script type="module">'));

for(const mode of ['attention','framing','mental'])write(out+'/downloads/ch2-evidence-'+mode+'.html',read(out+'/downloads/lesson-2-6.html').replace('<script type="module">','<script>window.EVIDENCE_DEFAULT='+JSON.stringify(mode)+';</script><script type="module">'));

for(const id of ['p1a','p1b','p1c','p1d','p1e','p2','p3qualified','p3none','p4qualified','p4none','p5a','p5b','p6','p7','p8'])write(out+'/downloads/ch2-exercise-'+id+'.html',read(out+'/downloads/lesson-2-6.html').replace('<script type="module">','<script>window.CHOICE_EXERCISE_DEFAULT='+JSON.stringify(id)+';</script><script type="module">'));

require('./src/guided/build.cjs').buildGuides(out,coverage).catch(err=>{console.error(err);process.exitCode=1;});
